INSERT INTO `cx_mantenimiento_encuestas` (`marca_temporal`,`1_en_una_escala_del_1_al_10_que_tan_prob`,`indice_de_recomendacion`,`tipo_de_cliente`,`2_como_calificarias_los_siguientes_compo`,`csat_mantenimiento`,`2_como_calificarias_los_siguientes_compo_1`,`csat_atencion_de_fallas`,`2_como_calificarias_los_siguientes_compo_2`,`csat_seguimiento_de_supervisor`,`2_como_calificarias_los_siguientes_compo_3`,`csat_cotizaciones_suministros_y_reparaci`,`2_como_calificarias_los_siguientes_compo_4`,`csat_facturacion`,`2_como_calificarias_los_siguientes_compo_5`,`csat_atencion_al_cliente`,`csat_general`,`2_1_cual_es_el_nombre_de_su_supervisor_o`,`3_1_mantenimiento_preventivo_oportunidad`,`3_2_atencion_de_fallas_oportunidad_de_me`,`3_3_seguimiento_de_supervisor_oportunida`,`3_4_cotizaciones_suministros_y_reparacio`,`3_5_facturacion_oportunidad_de_mejora`,`3_6_atencion_al_cliente_oportunidad_de_m`,`4_tengo_confianza_en_blt_para_la_operaci`,`indice_de_confianza`,`5_el_servicio_recibido_justifica_el_cost`,`percepcion_de_valor`,`6_pensando_en_el_futuro_que_tan_probable`,`indice_de_riesgo_churn`,`cuentanos_mas_sobre_tu_experiencia_algo_`,`proyecto_sitio_del_servicio`,`nombre`,`correo_electronico`,`telefono`,`cargo`,`medio_de_encuesta`,`encuestador`,`aspectos_destacables`,`areas_de_oportunidad`,`temas_operativos`,`temas_administrativos`,`valor_agregado`,`tickets_generados`,`z_general`,`z_operativa`,`z_administrativa`,`c_administrativo`,`z_ventas`,`c_ventas`,`z_contratos`,`c_contratos`,`superintendente`,`supervisor_operativo`,`categoria`,`prioridad`,`estado`,`id_de_encuesta`) VALUES ('2026-09-24 11:19:52.268000',9,9,'Promotor','Excelente',5,'Neutral',3,'Malo',2,'No lo conozco / No veo este proceso',0,'Neutral',3,'Bueno',4,3.4,'RAUL RIVAS',NULL,'Atención inicial del reporte (Call center), Tiempo de atención','Claridad de la comunicación, Atención y acompañamiento, Seguimiento hasta la solución',NULL,'Seguimiento al proceso, Precisión en la información de la facturación',NULL,'De acuerdo',4,'De acuerdo',4,'No lo consideraría',0,'Los técnicos que nos visitan mensualmente han tenido buena actitud y disposición, aunque constantemente nos los cambian. Considero que uno de los principales puntos a mejorar es la atención del Call Center, ya que al comunicarnos hemos llegado a esperar más de 30 minutos sin recibir respuesta. También los tiempos de atención son largos; por ejemplo, podemos levantar un reporte por la mañana y nos atienden hasta la noche o incluso al día siguiente. Entiendo que posiblemente cuenten con poco personal, pero considero importante que las emergencias tengan prioridad.

En cuanto al supervisor de zona, Raúl, hemos tenido temas de comunicación y seguimiento. En algunas ocasiones le solicitamos apoyo y no recibimos respuesta o tarda mucho en contestar; incluso en una ocasión nos comentó que había olvidado una solicitud que le habíamos realizado. Sin embargo, últimamente hemos notado una ligera mejora en este aspecto.

Respecto a facturación, tuvimos algunos problemas con la entrega por un tema relacionado con REPSE, lo cual generó demoras en el proceso.','Centro Comercial Perisur (PRUEBA)','Sandra Hernández (PRUEBA)','contacto.prueba25@lab-cx.test','55-0000-1025','Supervisora de mantenimiento ','Llamada / Remoto','Teresa Bazán','Buena percepción general del servicio y alta disposición para recomendar a BLT.','Mejorar retroalimentación posterior al mantenimiento, tiempos de atención y seguimiento hasta la solución.','Reforzar tiempos de atención y comunicación posterior a los mantenimientos.','Facturación evaluada favorablemente, sin áreas de oportunidad reportadas.','Mantiene confianza en BLT y considera adecuado el valor del servicio.',0,'CNA-01,A-2,V-1,C-1','CNA-01',2,'A-2','ADRIANA NERITH R SARMIENTO','V-1','IMELDA HERNANDEZ','C-1','CHRISTOPHER MEDINA','RAÚL RIVAS','COMERCIAL','PLUS','Ciudad de México','ENC-22');
INSERT INTO `cx_mantenimiento_encuestas` (`marca_temporal`,`1_en_una_escala_del_1_al_10_que_tan_prob`,`indice_de_recomendacion`,`tipo_de_cliente`,`2_como_calificarias_los_siguientes_compo`,`csat_mantenimiento`,`2_como_calificarias_los_siguientes_compo_1`,`csat_atencion_de_fallas`,`2_como_calificarias_los_siguientes_compo_2`,`csat_seguimiento_de_supervisor`,`2_como_calificarias_los_siguientes_compo_3`,`csat_cotizaciones_suministros_y_reparaci`,`2_como_calificarias_los_siguientes_compo_4`,`csat_facturacion`,`2_como_calificarias_los_siguientes_compo_5`,`csat_atencion_al_cliente`,`csat_general`,`2_1_cual_es_el_nombre_de_su_supervisor_o`,`3_1_mantenimiento_preventivo_oportunidad`,`3_2_atencion_de_fallas_oportunidad_de_me`,`3_3_seguimiento_de_supervisor_oportunida`,`3_4_cotizaciones_suministros_y_reparacio`,`3_5_facturacion_oportunidad_de_mejora`,`3_6_atencion_al_cliente_oportunidad_de_m`,`4_tengo_confianza_en_blt_para_la_operaci`,`indice_de_confianza`,`5_el_servicio_recibido_justifica_el_cost`,`percepcion_de_valor`,`6_pensando_en_el_futuro_que_tan_probable`,`indice_de_riesgo_churn`,`cuentanos_mas_sobre_tu_experiencia_algo_`,`proyecto_sitio_del_servicio`,`nombre`,`correo_electronico`,`telefono`,`cargo`,`medio_de_encuesta`,`encuestador`,`aspectos_destacables`,`areas_de_oportunidad`,`temas_operativos`,`temas_administrativos`,`valor_agregado`,`tickets_generados`,`z_general`,`z_operativa`,`z_administrativa`,`c_administrativo`,`z_ventas`,`c_ventas`,`z_contratos`,`c_contratos`,`superintendente`,`supervisor_operativo`,`categoria`,`prioridad`,`estado`,`id_de_encuesta`) VALUES ('2026-09-24 12:52:19.976000',8,8,'Pasivo','Malo',2,'Excelente',5,'Neutral',3,'Malo',2,'Excelente',5,'Excelente',5,3.666666667,'RAUL RIVAS','Programación de mantenimiento, Ejecución/cumplimiento del mantenimiento programado, Calidad del mantenimiento realizado, Información y retroalimentación posterior al mantenimiento',NULL,'Claridad de la comunicación, Atención y acompañamiento, Seguimiento hasta la solución, Actitud de servicio','Claridad del contenido de la cotización, Tiempo de envío de la cotización, Tiempo de suministro de los componentes, Ejecución de las reparaciones',NULL,NULL,'De acuerdo',4,'Neutral',3,'Lo he considerado',0.5,'He notado mucha rotación en el personal que realiza los mantenimientos y también variaciones en la programación, ya que en ocasiones se realizan a inicios de mes y otras veces hasta finales. Además, considero que la calidad del servicio ha disminuido, ya que anteriormente acudían dos técnicos y dedicaban aproximadamente un día por equipo, mientras que actualmente solo asiste un técnico y el mantenimiento se realiza en aproximadamente tres días en total. También dejaron de programarse servicios nocturnos, los cuales anteriormente sí se realizaban.

Otro punto importante es la falta de seguimiento y comunicación entre las diferentes áreas. Las cotizaciones tardan en llegar y, una vez autorizadas, el tiempo de suministro de las refacciones también suele ser prolongado. Actualmente tengo pendientes cotizaciones relacionadas con fotocelda, bisagras, una pieza dentro del panel de control de cabina y luminarias, y muchas veces somos nosotros quienes tenemos que dar seguimiento porque el área operativa no lo hace de manera oportuna.

También considero necesario mejorar la coordinación interna para la atención de fallas y equipos críticos. En algunas ocasiones, aun cuando una refacción ya está autorizada, por temas de liberación interna se retrasa su instalación, lo que termina prolongando la atención. En general, considero que la principal área de oportunidad es mejorar el seguimiento, la comunicación entre Operaciones y Ventas, y los tiempos de respuesta y suministro.','Hospital San Ángel Inn Patriotismo (PRUEBA)','Ing. Guillermo Hernández (PRUEBA)','contacto.prueba26@lab-cx.test','55-0000-1026','JEFE DE MATTO','Llamada / Remoto','Teresa Bazán','Sin comentarios positivos específicos; el cliente centró su retroalimentación en oportunidades de mejora del servicio.','Mejorar la calidad y programación del mantenimiento, así como el seguimiento, comunicación entre áreas y tiempos de cotización y suministro de refacciones.','Reducir rotación de técnicos, mantener una programación más consistente y asegurar tiempos adecuados de mantenimiento. Reforzar seguimiento a fallas, equipos críticos y refacciones pendientes.','Mejorar tiempos de envío de cotizaciones, suministro de refacciones y coordinación entre Operaciones y Ventas para evitar retrasos.','Brindar seguimiento proactivo y mayor comunicación entre áreas, evitando que el cliente tenga que solicitar constantemente avances de sus pendientes.',0,'CNA-01,A-2,V-1,C-1','CNA-01',2,'A-2','ADRIANA NERITH R SARMIENTO','V-1','IMELDA HERNANDEZ','C-1','CHRISTOPHER MEDINA','RAÚL RIVAS','HOSPITAL','ALTA','Ciudad de México','ENC-23');
